const queryCheck = Object.prototype.hasOwnProperty.call($json.query ?? {}, '--check');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').trim();
if (raw !== '' && raw !== '--check') throw new Error('Expected an empty body or --check');
return [{json: {check: queryCheck || raw === '--check'}}];
